import ast
from collections.abc import Mapping
from decimal import Decimal, ROUND_CEILING, ROUND_DOWN, ROUND_HALF_UP, ROUND_UP


def evaluate_decimal(expression, variables=None):
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")
    if not expression.strip():
        raise ValueError("expression must not be empty")
    if variables is None:
        variables = {}
    if not isinstance(variables, Mapping):
        raise TypeError("variables must be a mapping")
    env = {}
    for name, value in variables.items():
        if not isinstance(name, str) or not name.isidentifier():
            raise ValueError("invalid variable name")
        if isinstance(value, bool) or not isinstance(value, (Decimal, int, str)):
            raise TypeError("invalid variable value")
        try:
            number = Decimal(value)
        except Exception as exc:
            raise ValueError("invalid decimal value") from exc
        if not number.is_finite():
            raise ValueError("variables must be finite")
        env[name] = number
    try:
        root = ast.parse(expression, mode="eval")
    except SyntaxError as exc:
        raise ValueError("malformed expression") from exc

    def visit(node):
        if isinstance(node, ast.Expression):
            return visit(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
            return Decimal(ast.get_source_segment(expression, node))
        if isinstance(node, ast.Name):
            if node.id not in env:
                raise ValueError("unknown name")
            return env[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
            value = visit(node.operand)
            return value if isinstance(node.op, ast.UAdd) else -value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = visit(node.left), visit(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            if isinstance(node.op, ast.Sub):
                return left - right
            if isinstance(node.op, ast.Mult):
                return left * right
            return left / right
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            if node.keywords or len(node.args) != 2 or node.func.id not in {"nearest", "down", "ceiling"}:
                raise ValueError("invalid function call")
            value, digits_value = visit(node.args[0]), visit(node.args[1])
            if digits_value != digits_value.to_integral_value() or not 0 <= digits_value <= 12:
                raise ValueError("digits must be an integer from 0 through 12")
            quantum = Decimal(1).scaleb(-int(digits_value))
            modes = {"nearest": ROUND_HALF_UP, "down": ROUND_DOWN, "ceiling": ROUND_UP}
            return value.quantize(quantum, rounding=modes[node.func.id])
        raise ValueError("unsupported syntax")

    return visit(root)
```

