            if isinstance(node.op, ast.Add):
                return left + right
            if isinstance(node.op, ast.Sub):
                return left - right
            if isinstance(node.op, ast.Mult):
                return left * right
            return left / right
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            if node.keywords or len(node.args) != 2 or node.func.id not in {"nearest", "down", "ceiling"}:
                raise ValueError("invalid function call")
            value, digits_value = visit(node.args[0]), visit(node.args[1])
            if digits_value != digits_value.to_integral_value() or not 0 <= digits_value <= 12:
                raise ValueError("digits must be an integer from 0 through 12")
            quantum = Decimal(1).scaleb(-int(digits_value))
            modes = {"nearest": ROUND_HALF_UP, "down": ROUND_DOWN, "ceiling": ROUND_CEILING}
            return value.quantize(quantum, rounding=modes[node.func.id])
        raise ValueError("unsupported syntax")

    return visit(root)
